# ================================================================== pure numpy helpers (no bpy)
def smooth(t):
    t = np.clip(t, 0, 1); return t * t * (3 - 2 * t)

FIST = dict(x_axis=-0.040, mcp=((-0.045, 0.100), (0.06, 0.086)), seg=(0.040, 0.027), width=0.012,
            ang_mcp=((-0.04, 58), (0.0, 66), (0.03, 72), (0.06, 78)), ang_pip=((-0.04, 88), (0.06, 96)),
            ang_dip=((-0.04, 42), (0.06, 50)), thumb_deg=-34, thumb_base=(-0.03, 0.0, -0.035), thumb_axis=(0, 1, 0.35))

def _interp(z, pts):
    xs, ys = zip(*pts); return np.interp(z, xs, ys)

def curl(L, amount=1.0, mirror=False, prm=FIST):
    """Finger-curl displacement field in Hand bone rest space (smooth, never tears the mesh)."""
    L = np.array(L, float)
    if mirror: L[:, 0] *= -1
    y, z = L[:, 1], L[:, 2]
    ym = _interp(z, prm['mcp'])
    P = L.copy()
    joints = [(ym, _interp(z, prm['ang_mcp'])), (ym + prm['seg'][0], _interp(z, prm['ang_pip'])),
              (ym + prm['seg'][0] + prm['seg'][1], _interp(z, prm['ang_dip']))]
    for jy, ang in reversed(joints):
        s = smooth((P[:, 1] - jy) / prm['width'] + 0.5)
        t = np.radians(-ang * s * amount); cs, sn = np.cos(t), np.sin(t)
        dx = P[:, 0] - prm['x_axis']; dy = P[:, 1] - jy
        P = np.stack([prm['x_axis'] + dx * cs - dy * sn, jy + dx * sn + dy * cs, P[:, 2]], 1)
    base = np.array(prm['thumb_base']); a = np.array(prm['thumb_axis'], float); a /= np.linalg.norm(a)
    dist = np.linalg.norm(L[:, :2] - base[:2], axis=1)
    s = smooth((dist - 0.005) / 0.03)
    ang = np.radians(prm['thumb_deg'] * s * amount)[:, None]
    d = L - base
    Tm = base + d * np.cos(ang) + np.cross(a, d) * np.sin(ang) + np.outer(d @ a, a) * (1 - np.cos(ang))
    tw = smooth((-z - 0.050) / 0.014) * smooth((0.112 - y) / 0.02)
    fw = smooth((y + 0.005) / 0.02)
    out = L + fw[:, None] * ((1 - tw)[:, None] * (P - L) + tw[:, None] * (Tm - L))
    if mirror: out[:, 0] *= -1
    return out

def hand_region(L):
    return (L[:, 1] > -0.03) & (L[:, 1] < 0.26) & (np.abs(L[:, 0]) < 0.14) & (np.abs(L[:, 2]) < 0.14)

def fist_positions(P, hand_w, hand_mat, amount, mirror):
    """P: (N,3) rest vertex positions in armature space. Returns new positions and the changed mask."""
    Ph = np.c_[P, np.ones(len(P))]
    L = (np.linalg.inv(hand_mat) @ Ph.T).T[:, :3]
    m = hand_region(L) & (hand_w > 0.02)
    out = P.copy()
    Lc = curl(L[m], amount, mirror)
    out[m] = (hand_mat @ np.c_[Lc, np.ones(len(Lc))].T).T[:, :3]
    return out, m

def seg_dist(P, a, b):
    ab = b - a; t = np.clip(((P - a) @ ab) / (ab @ ab), 0, 1)
    return np.linalg.norm(P - (a + t[:, None] * ab), axis=1)

ARM_RADII = {'UpperArm': 0.12, 'Forearm': 0.10, 'Hand': 0.12}

def arm_bleed_fix(P, Wt, groups, head, tail, deform_bones, fade=0.03):
    """Vertices far from the arm (cape, chest panels) lose their arm weights, which go to the nearest
    non-arm deform bones (inverse distance^4). Returns (new weights, changed mask)."""
    Wn = Wt.astype(np.float64).copy(); changed = np.zeros(len(P), bool)
    arm_all = [f'{k}.{s}' for s in 'LR' for k in ('UpperArm', 'UpperArmTwist', 'Forearm', 'ForearmTwist', 'Hand')]
    cand = [b for b in deform_bones if b not in arm_all and b in groups]
    cd = np.stack([seg_dist(P, head[b], tail[b]) for b in cand], 1)
    for s in 'LR':
        rel = np.min([seg_dist(P, head[f'{k}.{s}'], tail[f'{k}.{s}']) - r for k, r in ARM_RADII.items()], axis=0)
        gi = [groups.index(f'{k}.{s}') for k in ('UpperArm', 'UpperArmTwist', 'Forearm', 'ForearmTwist', 'Hand') if f'{k}.{s}' in groups]
        aw = Wn[:, gi].sum(1)
        keep = np.clip(1 - rel / fade, 0, 1)
        m = (aw > 1e-4) & (keep < 1)
        removed = aw[m] * (1 - keep[m])
        Wn[np.ix_(m, gi)] *= keep[m][:, None]
        d = cd[m]; nn = np.argsort(d, 1)[:, :3]
        dn = np.take_along_axis(d, nn, 1) + 0.01
        wn = 1 / dn ** 4; wn /= wn.sum(1, keepdims=True)
        rows = np.where(m)[0]
        for k in range(3):
            cols = np.array([groups.index(cand[j]) for j in nn[:, k]], dtype=int)
            np.add.at(Wn, (rows, cols), removed * wn[:, k])
        changed |= m
    Wn /= Wn.sum(1, keepdims=True) + 1e-12
    return Wn.astype(np.float32), changed

def sword_canonical_matrix(P, length, grip_fraction):
    """Find the sword's blade axis / pommel end / edge direction from its geometry and return a 4x4 matrix that maps
    mesh coords -> (x = edge, y = blade from the grip, z = flat), origin at the grip, scaled to `length`."""
    c = P.mean(0)
    sub = P[:: max(1, len(P) // 30000)]
    _, _, Vt = np.linalg.svd(sub - c, full_matrices=False)
    ax = Vt[0]
    t = (P - c) @ ax
    L = t.max() - t.min()
    nb = 40
    bins = np.clip(((t - t.min()) / L * nb).astype(int), 0, nb - 1)
    perp = (P - c) - np.outer(t, ax)
    r = np.linalg.norm(perp, axis=1)
    width = np.array([r[bins == i].max() if np.any(bins == i) else 0 for i in range(nb)])
    g = int(np.argmax(width))
    if g > nb / 2:                       # crossguard is nearer the pommel: make the pommel the low end
        ax = -ax; t = -t; bins = nb - 1 - bins; g = nb - 1 - g
    pommel = t.min()
    gv = perp[bins == g]
    _, _, Vg = np.linalg.svd(gv - gv.mean(0), full_matrices=False)
    edge = Vg[0] - np.dot(Vg[0], ax) * ax; edge /= np.linalg.norm(edge)
    flat = np.cross(edge, ax)
    gt = pommel + grip_fraction * L
    sel = np.abs(t - gt) < 0.04 * L
    gc = P[sel].mean(0); gc = gc + ax * (gt - np.dot(gc - c, ax))   # point on the grip axis at the fist position
    s = length / L
    R = np.stack([edge, ax, flat])        # rows
    M = np.eye(4); M[:3, :3] = R * s; M[:3, 3] = -(R * s) @ gc
    return M

def reshape_blade(Sc):
    Sc = np.array(Sc, float); y = Sc[:, 1]
    s = np.clip((y - BLADE_START) / 0.05, 0, 1); s = s * s * (3 - 2 * s)
    out = Sc.copy()
    out[:, 1] = np.where(y > BLADE_START, BLADE_START + (y - BLADE_START) * BLADE_LEN_SCALE, y)
    out[:, 0] = Sc[:, 0] * (1 + (BLADE_WIDTH_SCALE - 1) * s)
    out[:, 2] = Sc[:, 2] * (1 + (BLADE_THICK_SCALE - 1) * s)
    return out

def weld_edges(P, T, tol=2e-5):
    q = np.round(P / tol).astype(np.int64)
    _, inv = np.unique(q, axis=0, return_inverse=True); inv = inv.ravel()
    TT = inv[T]
    e = np.concatenate([TT[:, [0, 1]], TT[:, [1, 2]], TT[:, [2, 0]]])
    e = np.sort(e, 1); e = e[e[:, 0] != e[:, 1]]
    e = np.unique(e, axis=0)
    return inv, e

def smooth_weights(W, inv, edges, alpha, iters, lock=None, max_infl=4):
    """W: (N, G) per original vertex. alpha: (Nw,) per welded vertex smoothing strength (0..1)."""
    nw = inv.max() + 1; G = W.shape[1]
    cnt = np.bincount(inv, minlength=nw).astype(np.float64)
    Ww = np.zeros((nw, G))
    for g in range(G): Ww[:, g] = np.bincount(inv, weights=W[:, g], minlength=nw) / cnt
    a, b = edges[:, 0], edges[:, 1]
    deg = np.bincount(a, minlength=nw) + np.bincount(b, minlength=nw); deg = np.maximum(deg, 1).astype(np.float64)
    al = alpha[:, None]
    for _ in range(iters):
        nb = np.zeros_like(Ww)
        for g in range(G):
            nb[:, g] = (np.bincount(a, weights=Ww[b, g], minlength=nw) + np.bincount(b, weights=Ww[a, g], minlength=nw)) / deg
        Ww = Ww * (1 - al) + nb * al
    # keep max_infl largest, renormalise
    if max_infl:
        idx = np.argsort(-Ww, 1)[:, max_infl:]
        np.put_along_axis(Ww, idx, 0.0, 1)
    Ww[Ww < 0.01] = 0
    Ww /= Ww.sum(1, keepdims=True) + 1e-12
    return Ww[inv].astype(np.float32)

def final_weights(P, T, W0, groups, head, tail, deform, arm_bleed_fix, weld_edges, smooth_weights):
    W1, _ = arm_bleed_fix(P, W0, groups, head, tail, deform)
    inv, e = weld_edges(P, T)
    nw = inv.max() + 1
    cnt = np.bincount(inv, minlength=nw)
    def per_w(x): return np.bincount(inv, weights=x, minlength=nw) / cnt
    hand = per_w(W1[:, groups.index('Hand.R')] + W1[:, groups.index('Hand.L')])
    headw = per_w(W1[:, groups.index('Head')])
    soft_g = [i for i, g in enumerate(groups) if g.startswith(('Cape', 'FrontRobe', 'SideRobe', 'Belt', 'Hips', 'Thigh', 'Clavicle'))]
    soft = per_w(W1[:, soft_g].sum(1))
    W2 = smooth_weights(W1, inv, e, np.where(hand > 0.3, 0.0, np.where(headw > 0.5, 0.15, 0.5)), 10)
    W2 = smooth_weights(W2, inv, e, np.where((soft > 0.15) & (hand < 0.3), 0.5, 0.0), 25)
    return W2


def blade_shell(Sc, blade_start, inflate=0.012, n_sec=36):
    """loft a low-poly shell around the blade part of canonical sword verts Sc (x edge, y blade, z flat)."""
    y = Sc[:, 1]; m = y > blade_start
    y0, y1 = blade_start, y[m].max()
    ys = np.linspace(y0, y1, n_sec)
    secs = []
    for k in range(n_sec - 1):
        s = m & (y >= ys[k]) & (y < ys[k + 1] + 1e-6)
        if s.sum() < 3:
            secs.append(secs[-1] if secs else (0.03, 0.006, 0.0)); continue
        xc = 0.5 * (Sc[s, 0].max() + Sc[s, 0].min())
        secs.append((0.5 * (Sc[s, 0].max() - Sc[s, 0].min()), 0.5 * (Sc[s, 2].max() - Sc[s, 2].min()), xc))
    secs.append((0.0, 0.0, secs[-1][2]))
    V = []; F = []
    ring = 6
    ang = np.linspace(0, 2 * np.pi, ring, endpoint=False)
    shape = np.stack([np.cos(ang), np.sin(ang) * 1.0], 1)          # hexagonal section: edges at +-x
    for k, (w, t, xc) in enumerate(secs):
        w2 = w + inflate if k < n_sec - 1 else 0.0; t2 = t + inflate * 0.8 if k < n_sec - 1 else 0.0
        for a in shape:
            V.append((xc + a[0] * w2, ys[k], a[1] * t2))
    for k in range(n_sec - 1):
        for j in range(ring):
            a = k * ring + j; b = k * ring + (j + 1) % ring; c = a + ring; d = b + ring
            F += [(a, b, d), (a, d, c)]
    # cap at the guard
    base = len(V); V.append((secs[0][2], ys[0], 0.0))
    for j in range(ring): F.append((base, (j + 1) % ring, j))
    return np.array(V, float), np.array(F, int)

def portal_mesh(R=0.20):
    """disc in the local XZ plane (normal +Y). parts: (name, V, F, color, alpha)."""
    parts = []
    # outer ring (torus)
    nu, nv, r = 48, 8, 0.016
    u = np.linspace(0, 2 * np.pi, nu, endpoint=False); v = np.linspace(0, 2 * np.pi, nv, endpoint=False)
    V = []; F = []
    for a in u:
        for b in v:
            V.append(((R + r * np.cos(b)) * np.cos(a), r * np.sin(b), (R + r * np.cos(b)) * np.sin(a)))
    for i in range(nu):
        for j in range(nv):
            a = i * nv + j; b = ((i + 1) % nu) * nv + j; c = i * nv + (j + 1) % nv; d = ((i + 1) % nu) * nv + (j + 1) % nv
            F += [(a, b, d), (a, d, c)]
    parts.append(('Portal_Ring', np.array(V), np.array(F), (0.35, 0.80, 1.0), 1.0))
    # swirl: 5 spiral arms (thin ribbons)
    V = []; F = []
    for arm in range(5):
        base = len(V); n = 40
        for i in range(n):
            t = i / (n - 1); ang = arm * 2 * np.pi / 5 + t * 3.2
            rad = R * (0.12 + 0.86 * t); wdt = 0.010 + 0.022 * np.sin(np.pi * t)
            ca, sa = np.cos(ang), np.sin(ang)
            nx, nz = -sa, ca
            V.append((ca * rad - nx * wdt, 0.002 * arm, sa * rad - nz * wdt)); V.append((ca * rad + nx * wdt, 0.002 * arm, sa * rad + nz * wdt))
        for i in range(n - 1):
            a = base + 2 * i; F += [(a, a + 1, a + 3), (a, a + 3, a + 2)]
    parts.append(('Portal_Swirl', np.array(V), np.array(F), (0.45, 0.35, 1.0), 0.75))
    # dark core
    n = 32; ang = np.linspace(0, 2 * np.pi, n, endpoint=False)
    V = [(0, -0.003, 0)] + [(np.cos(a) * R * 0.92, -0.003, np.sin(a) * R * 0.92) for a in ang]
    F = [(0, 1 + (i + 1) % n, 1 + i) for i in range(n)]
    parts.append(('Portal_Core', np.array(V, float), np.array(F), (0.05, 0.02, 0.15), 0.85))
    return parts



def unpack_actions():
    meta = ANIM['meta']; nb = len(meta['bones']); nf = len(meta['fx_bones'])
    out = {}
    for name, (b64a, b64f) in ANIM['blob'].items():
        n = meta['frames'][name]
        a = np.frombuffer(zlib.decompress(base64.b64decode(b64a)), dtype=np.float32).reshape(n, nb, 7)
        f = np.frombuffer(zlib.decompress(base64.b64decode(b64f)), dtype=np.float32).reshape(n, nf, 10)
        out[name] = (a, f)
    return out

# ================================================================== Blender side
def log(*a):
    print('[hero-v3]', *a)

def np_mat(m):
    return np.array([list(r) for r in m], float)

def mesh_coords(me):
    co = np.empty(len(me.vertices) * 3, np.float32); me.vertices.foreach_get('co', co)
    return co.reshape(-1, 3).astype(np.float64)

def mesh_triangles(me):
    me.calc_loop_triangles()
    tri = np.empty(len(me.loop_triangles) * 3, np.int32); me.loop_triangles.foreach_get('vertices', tri)
    return tri.reshape(-1, 3)

def read_weights(obj):
    me = obj.data; ng = len(obj.vertex_groups)
    W = np.zeros((len(me.vertices), ng), np.float32)
    for v in me.vertices:
        for g in v.groups:
            if g.group < ng: W[v.index, g.group] = g.weight
    return W

def write_weights(obj, W_old, W_new, rows):
    vgs = obj.vertex_groups
    rows = np.asarray(rows, dtype=np.int64)
    if len(rows) == 0: return 0
    rl = rows.tolist()
    for vg in vgs: vg.remove(rl)
    Q = np.round(W_new[rows] * 1024).astype(np.int32)
    n = 0
    for g in range(W_new.shape[1]):
        col = Q[:, g]; nz = np.nonzero(col)[0]
        if len(nz) == 0: continue
        for qv in np.unique(col[nz]):
            vgs[g].add(rows[nz[col[nz] == qv]].tolist(), float(qv) / 1024.0, 'REPLACE'); n += 1
    return n

def emissive_mat(name, color, strength, alpha):
    m = bpy.data.materials.get(name) or bpy.data.materials.new(name)
    try: m.use_nodes = True
    except Exception: pass
    p = next((n for n in m.node_tree.nodes if n.type == 'BSDF_PRINCIPLED'), None)
    if p is not None:
        p.inputs['Base Color'].default_value = (*color, 1.0)
        for k in ('Emission Color', 'Emission'):
            if k in p.inputs: p.inputs[k].default_value = (*color, 1.0)
        if 'Emission Strength' in p.inputs: p.inputs['Emission Strength'].default_value = strength
        if 'Alpha' in p.inputs: p.inputs['Alpha'].default_value = alpha
    for attr, val in (('surface_render_method', 'BLENDED'), ('blend_method', 'BLEND'), ('use_backface_culling', False),
                      ('shadow_method', 'NONE')):
        try: setattr(m, attr, val)
        except Exception: pass
    return m

def make_mesh_obj(name, V, F, mat, rig, bone):
    old = bpy.data.objects.get(name)
    if old: bpy.data.objects.remove(old, do_unlink=True)
    me = bpy.data.meshes.new(name); me.from_pydata([tuple(map(float, v)) for v in V], [], [tuple(map(int, f)) for f in F]); me.update()
    me.materials.append(mat)
    ob = bpy.data.objects.new(name, me)
    (rig.users_collection[0] if rig.users_collection else bpy.context.scene.collection).objects.link(ob)
    attach(ob, rig, bone)
    return ob

def attach(ob, rig, bone):
    ob.parent = rig; ob.parent_type = 'BONE'; ob.parent_bone = bone
    ob.matrix_parent_inverse = Matrix.Identity(4)
    ob.matrix_basis = Matrix.Translation((0, -rig.data.bones[bone].length, 0))

def create_bones(rig):
    bpy.context.view_layer.objects.active = rig
    for o in bpy.context.selected_objects: o.select_set(False)
    rig.select_set(True)
    bpy.ops.object.mode_set(mode='EDIT')
    eb = rig.data.edit_bones
    hand = eb['Hand.R']; Hm = hand.matrix.copy()
    G = Matrix([list(r) + [0.0] for r in R_SWORD_IN_HAND] + [[0, 0, 0, 1.0]]); G.translation = Vector(GRIP_IN_HAND)
    def mk(name, M, parent):
        b = eb.get(name) or eb.new(name)
        b.head = (0, 0, 0); b.tail = (0, 0.1, 0); b.roll = 0.0
        b.matrix = M
        b.parent = parent; b.use_connect = False; b.use_deform = False
    mk('Sword_Grip', Hm @ G, hand)
    mk('Sword_Aura', Hm @ G, eb['Sword_Grip'])
    for n in ('Sword_Ghost1', 'Sword_Ghost2', 'Sword_Ghost3', 'Sword_Ghost4', 'Sword_Portal', 'Fist_Ctrl'):
        mk(n, Matrix.Identity(4), None)
    bpy.ops.object.mode_set(mode='OBJECT')
    for pb in rig.pose.bones: pb.rotation_mode = 'QUATERNION'
    log('helper bones created')

def import_sword(rig):
    path = bpy.path.abspath(SWORD_GLB)
    if not os.path.isfile(path):
        raise FileNotFoundError(f"Sword GLB not found: {path}  -> edit SWORD_GLB at the top of the script")
    old = bpy.data.objects.get(SWORD_NAME)
    if old: bpy.data.objects.remove(old, do_unlink=True)
    before = set(bpy.data.objects)
    bpy.ops.import_scene.gltf(filepath=path)
    new = [o for o in bpy.data.objects if o not in before]
    meshes = [o for o in new if o.type == 'MESH']
    if not meshes: raise RuntimeError("No mesh found in the sword GLB")
    for o in meshes:
        mw = o.matrix_world.copy(); o.parent = None
        o.data.transform(mw); o.matrix_world = Matrix.Identity(4)
    sw = meshes[0]
    if len(meshes) > 1:
        with bpy.context.temp_override(active_object=sw, selected_editable_objects=meshes, selected_objects=meshes):
            bpy.ops.object.join()
    for o in new:
        if o.name in bpy.data.objects and o != sw and o.type != 'MESH':
            bpy.data.objects.remove(o, do_unlink=True)
    sw.name = SWORD_NAME
    M = sword_canonical_matrix(mesh_coords(sw.data), SWORD_LENGTH, GRIP_FRACTION)
    sw.data.transform(Matrix(M.tolist()))
    Pc = reshape_blade(mesh_coords(sw.data))
    sw.data.vertices.foreach_set('co', Pc.astype(np.float32).ravel()); sw.data.update()
    attach(sw, rig, 'Sword_Grip')
    log('sword attached to Sword_Grip')
    return Pc

def build_fx(rig, Pc):
    V, F = blade_shell(Pc, BLADE_START)
    make_mesh_obj('Hero_Sword_Aura', V, F, emissive_mat('FX_Sword_Aura', AURA_COLOR, 6.0, 0.45), rig, 'Sword_Aura')
    for k in range(4):
        make_mesh_obj(f'Hero_Sword_Ghost{k + 1}', V, F, emissive_mat(f'FX_Sword_Ghost{k + 1}', AURA_COLOR, 4.0, GHOST_ALPHA[k]), rig, f'Sword_Ghost{k + 1}')
    for name, Vp, Fp, col, alpha in portal_mesh():
        make_mesh_obj('Hero_' + name, Vp, Fp, emissive_mat('FX_' + name, col, 0.3 if 'Core' in name else 8.0, alpha), rig, 'Sword_Portal')
    log('FX meshes created')

def fix_mesh(rig, hero):
    me = hero.data
    groups = [vg.name for vg in hero.vertex_groups]
    to_arm = np_mat(rig.matrix_world.inverted() @ hero.matrix_world)
    P_obj = mesh_coords(me)
    P = (to_arm @ np.c_[P_obj, np.ones(len(P_obj))].T).T[:, :3]
    log('reading skin weights for', len(P), 'vertices ...')
    W0 = read_weights(hero)
    bones = rig.data.bones
    head = {b.name: np.array(b.head_local) for b in bones}
    tail = {b.name: np.array(b.tail_local) for b in bones}
    if me.shape_keys is None:
        hero.shape_key_add(name='Basis', from_mix=False)
    for kname in list(me.shape_keys.key_blocks.keys()):
        if kname.startswith('Fist_'): hero.shape_key_remove(me.shape_keys.key_blocks[kname])
    back = np.linalg.inv(to_arm)
    for side, kname, chan in (('R', 'Fist_R', 'LOC_X'), ('L', 'Fist_L', 'LOC_Z')):
        hm = np_mat(bones[f'Hand.{side}'].matrix_local)
        newP, m = fist_positions(P, W0[:, groups.index(f'Hand.{side}')], hm, 1.0, side == 'L')
        newObj = (back @ np.c_[newP, np.ones(len(newP))].T).T[:, :3]
        basis = np.empty(len(me.vertices) * 3, np.float32); me.shape_keys.reference_key.data.foreach_get('co', basis)
        basis = basis.reshape(-1, 3); basis[m] = newObj[m]
        key = hero.shape_key_add(name=kname, from_mix=False)
        key.data.foreach_set('co', basis.ravel())
        fc = key.driver_add('value'); d = fc.driver; d.type = 'AVERAGE'
        for v in list(d.variables): d.variables.remove(v)
        var = d.variables.new(); var.name = 'amount'; var.type = 'TRANSFORMS'
        t = var.targets[0]; t.id = rig; t.bone_target = 'Fist_Ctrl'; t.transform_type = chan; t.transform_space = 'LOCAL_SPACE'
        log(f'shape key {kname}: {int(m.sum())} vertices (driven by Fist_Ctrl {chan})')
    if FIX_ARM_WEIGHTS:
        deform = [b.name for b in bones if b.use_deform]
        T = mesh_triangles(me)
        log('cleaning + smoothing skin weights (about a minute) ...')
        Wn = final_weights(P, T, W0, groups, head, tail, deform, arm_bleed_fix, weld_edges, smooth_weights)
        changed = np.nonzero(np.abs(Wn - W0).max(1) > 1e-5)[0]
        n = write_weights(hero, W0, Wn, changed)
        log(f'skin weights updated on {len(changed)} vertices ({n} weight edits)')

def key_clip(rig, ad, name, arr, fx, bones_keep=None):
    meta = ANIM['meta']
    old = bpy.data.actions.get(name)
    if old: bpy.data.actions.remove(old)
    act = bpy.data.actions.new(name); act.use_fake_user = True
    ad.action = act
    body = [(j, rig.pose.bones[b]) for j, b in enumerate(meta['bones']) if bones_keep is None or b in bones_keep]
    fxb = [(j, rig.pose.bones[b]) for j, b in enumerate(meta['fx_bones'])]
    loc_bones = set(meta['loc_bones'])
    n = arr.shape[0]
    for f in range(n):
        for j, pb in body:
            pb.rotation_quaternion = [float(x) for x in arr[f, j, 3:]]
            pb.keyframe_insert('rotation_quaternion', frame=f, group=pb.name)
            if pb.name in loc_bones:
                pb.location = [float(x) for x in arr[f, j, :3]]
                pb.keyframe_insert('location', frame=f, group=pb.name)
        for j, pb in fxb:
            v = fx[f, j]
            pb.location = [float(x) for x in v[:3]]; pb.keyframe_insert('location', frame=f, group=pb.name)
            if pb.name != 'Fist_Ctrl':
                pb.rotation_quaternion = [float(x) for x in v[3:7]]; pb.keyframe_insert('rotation_quaternion', frame=f, group=pb.name)
                pb.scale = [float(x) for x in v[7:10]]; pb.keyframe_insert('scale', frame=f, group=pb.name)
    act.use_frame_range = True
    act.frame_start, act.frame_end = 0, n - 1
    base = name.replace('_Upper', '')
    if base in LOOPING: act.use_cyclic = True
    for h in meta['hits'].get(base, []):
        mk = act.pose_markers.new('hit'); mk.frame = int(h)
    if base == 'Hero_Attack_Combo':
        for i, b0 in enumerate(meta['bounds'][:-1]):
            for h in meta['hits'].get(f'Hero_Attack{i + 1}', []):
                mk = act.pose_markers.new(f'hit {i + 1}'); mk.frame = int(b0 + h)
    log(f'action {name}: {n} frames')
    return act

def build_actions(rig):
    meta = ANIM['meta']; data = unpack_actions()
    ad = rig.animation_data or rig.animation_data_create()
    for name, (arr, fx) in data.items():
        key_clip(rig, ad, name, arr, fx)
        if name in ('Hero_Sword_Summon', 'Hero_Sword_Dismiss'):
            key_clip(rig, ad, name + '_Upper', arr, fx, bones_keep=set(UPPER_BONES))
    for k, v in meta['speeds'].items(): rig[f'speed_{k}_mps'] = float(v)
    act = bpy.data.actions.get(ACTIVE_ACTION); ad.action = act
    sc = bpy.context.scene
    sc.render.fps = 30; sc.render.fps_base = 1.0
    sc.frame_start = 0; sc.frame_end = int(act.frame_end); sc.frame_set(0)

def main():
    rig = bpy.data.objects.get(RIG_NAME); hero = bpy.data.objects.get(MESH_NAME)
    if rig is None or hero is None:
        raise RuntimeError(f"Need objects '{RIG_NAME}' and '{MESH_NAME}' — open the original hero-rigged-2.blend first")
    if bpy.context.object and bpy.context.object.mode != 'OBJECT':
        bpy.ops.object.mode_set(mode='OBJECT')
    rig.data.pose_position = 'POSE'
    create_bones(rig)
    Pc = import_sword(rig)
    build_fx(rig, Pc)
    fix_mesh(rig, hero)
    build_actions(rig)
    out = bpy.path.abspath(OUTPUT_BLEND)
    bpy.ops.wm.save_as_mainfile(filepath=out)
    log('saved', out)

if __name__ == "__main__":
    main()
